#!/usr/bin/env python3
"""Native-QC complete five-type visits and frozen biological pair selection."""
from pathlib import Path
import pandas as pd,json,datetime
P=Path(__file__).resolve().parents[2];O=P/'outputs/round6';W=P/'work/round6';CTS=['B','CD4T','CD8T','MONO','NK']
def main():
 assert json.loads((O/'K_b_status.json').read_text())['status']=='PASS';receipts=json.loads((O/'K_c_metadata_download_receipts.json').read_text());available={r['celltype']:r for r in receipts if 'metadata_path'in r};assert set(available)>={'CD4T','CD8T','MONO','NK'}
 paths={'B':W/'extracted/b_cells_metadata.csv',**{ct:P/available[ct]['metadata_path'] for ct in available}};counts=[];clusters=[];obs=[]
 for ct in CTS:
  z=pd.read_csv(paths[ct],index_col=0);assert z.index.is_unique and z[['Donor_id','Tube_id','Age','nFeature_RNA','nCount_RNA','percent.mt']].notna().all().all();keep=pd.Series(True,index=z.index)
  if ct=='B':keep&=z.Cluster_names.ne('Plasma cells')
  if ct=='MONO':keep&=z.Cluster_names.isin(['Classical monocytes','Non-classical monocytes'])
  if ct=='CD8T':keep&=z.Cluster_names.ne('NKT-like')
  for cl,g in z.groupby('Cluster_names'):clusters.append({'source_major_file':ct,'source_cluster':cl,'n_cells_source':len(g),'retained_for_A1_type':bool(keep.loc[g.index].all()),'reason':'A1conventionallineagecrosswalk;plasma/DC/ambiguousNKTlikeexcluded' if not keep.loc[g.index].all() else 'sourceconventionallineage'})
  qc=z.nFeature_RNA.ge(200)&z.nFeature_RNA.le(5000)&z['percent.mt'].le(25)&z.nCount_RNA.gt(0);summary=z.groupby(['Donor_id','Tube_id']).size().rename('n_source_cells').to_frame();summary['n_lineage_cells']=z[keep].groupby(['Donor_id','Tube_id']).size();summary['n_native_QC_cells']=z[keep&qc].groupby(['Donor_id','Tube_id']).size();summary=summary.fillna(0).astype(int).reset_index().rename(columns={'Donor_id':'donor','Tube_id':'visit'});summary['celltype']=ct;summary['meets30']=summary.n_native_QC_cells.ge(30);counts.append(summary);g=z[keep&qc].copy();g['celltype']=ct;g['barcode']=g.index;obs.append(g[['barcode','Donor_id','Tube_id','Age','File_name','Batch','nCount_RNA','nFeature_RNA','percent.mt','celltype']]);print('Kc_TYPE',ct,len(z),len(g),summary.meets30.sum(),flush=True)
 c=pd.concat(counts,ignore_index=True);c.to_csv(O/'K_c_all_donor_visit_type_cell_counts.csv',index=False);pd.DataFrame(clusters).to_csv(O/'K_c_A1_lineage_crosswalk.csv',index=False);wide=c.pivot(index=['donor','visit'],columns='celltype',values='n_native_QC_cells').fillna(0).astype(int);wide['all_five_ge30']=wide[CTS].ge(30).all(axis=1);wide.reset_index().to_csv(O/'K_c_complete_visit_ledger.csv',index=False);summary=[]
 for ct in CTS:
  x=c[c.celltype.eq(ct)&c.meets30];n=x.groupby('donor').visit.nunique();summary.append({'celltype':ct,'n_visits_ge30':len(x),'n_donors_any_visit_ge30':len(n),'n_donors_ge2visits_ge30':int(n.ge(2).sum())})
 vv=pd.read_csv(O/'K_b_donor_visit_wave_ledger.csv').rename(columns={'Donor_id':'donor','Tube_id':'visit'});eligible_visits=wide[wide.all_five_ge30].reset_index()[['donor','visit']].merge(vv,on=['donor','visit'],validate='one_to_one');n=eligible_visits.groupby('donor').size();donors=set(n[n.ge(2)].index);cohort=eligible_visits[eligible_visits.donor.isin(donors)].sort_values(['donor','visit_wave']);summary.append({'celltype':'ALL_FIVE_INTERSECTION','n_visits_ge30':int(wide.all_five_ge30.sum()),'n_donors_any_visit_ge30':int(wide[wide.all_five_ge30].reset_index().donor.nunique()),'n_donors_ge2visits_ge30':len(donors)});pd.DataFrame(summary).to_csv(O/'K_c_qualifying_donor_counts.csv',index=False)
 status={'gate':'K-c','status':'PASS' if len(donors)>=15 else 'FAIL','recorded_UTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'minimum_cells_per_type_per_visit':30,'native_QC':'200<=nFeature_RNA<=5000;percent.mt<=25;nCount_RNA>0;librarydenominator never subsetgene sum','lineage':'B excludes plasma;MONO only classical/nonclassicalmonocytes,notDC;CD8 excludes ambiguousNKTlike;sourceCD4/NKmajorlineage retained','qualifying_counts':summary,'n_complete_paired_donors':len(donors),'n_common_eligible_analysis_visits':len(cohort),'LODO_calibration_scope':'all commoncompletevisits of eligiblepaired donors,includingmiddlevisit ifavailable;equal totaldonorweight;ICCearliest-latestonepairperdonor;no singlevisit-only donors in calibration','counts_basis':'source per-cellQC fields;B fieldsmatch fullmatrix exactly. Everyother sourcecountmatrix must pass same integer/library/feature QA beforeanypredictions;metadata itself not substituted for expression.'};(O/'K_c_status.json').write_text(json.dumps(status,indent=2));f=P/'outputs/gate_ledger.json';led=json.loads(f.read_text());led['round6']['K_c_result']=status;f.write_text(json.dumps(led,ensure_ascii=False,indent=2));print(json.dumps(status,indent=2),flush=True)
 if status['status']=='FAIL':return
 cohort.to_csv(O/'external_primary_donor_visit_ledger.csv',index=False);rows=[]
 for d,g in cohort.groupby('donor'):
  a,b=g.iloc[0],g.iloc[-1];rows.append({'donor':d,'gsm1':a.visit,'gsm2':b.visit,'stratum':'nominalannual_earliest_latest','visit_wave_gap':b.visit_wave-a.visit_wave,'interval_nominal_years':b.visit_wave-a.visit_wave,'interval_actual_days':None,'age1':a.Age_min,'age2':b.Age_min,'integer_age_difference_NOT_interval':b.Age_min-a.Age_min})
 pairs=pd.DataFrame(rows);pairs.to_csv(O/'external_primary_pair_ledger.csv',index=False);pairs.groupby('interval_nominal_years').size().reset_index(name='n_pairs').to_csv(O/'external_primary_nominal_interval_distribution.csv',index=False);ob=pd.concat(obs,ignore_index=True).rename(columns={'Donor_id':'donor','Tube_id':'gsm','Age':'age'});keys=set(zip(cohort.donor,cohort.visit));ob=ob[[k in keys for k in zip(ob.donor,ob.gsm)]].copy();assert ob.groupby(['donor','gsm','celltype']).size().ge(30).all();ob.to_parquet(W/'primary_selected_cells.parquet',index=False);batches=ob[['donor','gsm','celltype','Batch']].drop_duplicates().groupby(['donor','gsm','celltype']).Batch.apply(lambda x:'|'.join(sorted(set(map(str,x))))).reset_index();batches.to_csv(O/'external_primary_batch_ledger.csv',index=False)
 (O/'primary_population_freeze.json').write_text(json.dumps({'status':'FROZEN_BEFORE_ANY_CLOCK_PREDICTION','seed':20261025,'recorded_UTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'n_donors':len(donors),'n_visits':len(cohort),'n_cells':len(ob),'n_pairs':len(pairs),'selection':'metadata/QC only;all completeeligiblepairs;LODOusesallcommonvisits of these donors','no_clock_values_used':True},indent=2))
if __name__=='__main__':main()
